import { useContext } from '@soybeanjs/headless/composables';
import type { ConfigProviderContext } from './types';

export const [provideConfigProviderContext, useConfigProvider] = useContext<ConfigProviderContext>('UiConfigProvider');

import type { ConfigProviderProps as _ConfigProviderProps } from '@soybeanjs/headless/config-provider';
import type { ProgressProviderProps } from '@soybeanjs/headless/progress';
import type { PropsToContext } from '@soybeanjs/headless/types';
import type { ThemeOptions } from '@soybeanjs/theme';
import type { CustomThemeColorPreset, ThemeConfigState, ThemePresetInput } from '@soybeanjs/theme/storage';
import type { ThemeSize } from '@/theme';
import type { ToastProviderProps } from '../toast/types';

/**
 * UI-level theme options accepted by `SConfigProvider`.
 *
 * The engine's `ThemeOptions` now carries `overrides` for inline token
 * overrides. The provider additionally accepts a legacy `preset` input — either
 * an inline mode-split override or a `{ name }` reference to a stored preset.
 * The provider resolves named references to their colors and materializes the
 * result as `overrides` before calling `createTheme`, so the engine only ever
 * receives resolved options.
 */
export type ConfigProviderThemeOptions = ThemeOptions & {
  /**
   * A custom color preset: either an inline mode-split override (light/dark
   * partial tokens) or a `{ name }` reference to a stored preset. Resolved to
   * `overrides` before `createTheme`.
   */
  preset?: ThemePresetInput;
};

export interface IconifyOptions {
  /**
   * The default width of the icon.
   *
   * @defaultValue '1.25em'
   */
  width?: string;
  /**
   * The default height of the icon.
   *
   * @defaultValue '1.25em'
   */
  height?: string;
}

/**
 * Properties for the ConfigProvider component.
 */
export interface ConfigProviderProps extends _ConfigProviderProps {
  /** The theme options. */
  theme?: ConfigProviderThemeOptions;
  /**
   * The size options.
   *
   * @deprecated Use `theme.size` instead.
   */
  size?: ThemeSize;
  /** The iconify options. */
  iconify?: IconifyOptions;
  /** The global top progress configuration of your application. */
  progress?: Partial<ProgressProviderProps>;
  /** The global toast configuration of your application. This will be inherited by the related components. */
  toast?: Partial<ToastProviderProps>;
  /**
   * Whether to use custom toast rendering. If set to `true`, the `ToastProvider` will not render the default toast UI, and you can import `ToastProvider` component to render custom toast UI.
   *
   * @default false
   */
  customToast?: boolean;
  /**
   * Whether to enable persisted theme reading from localStorage / cookie.
   *
   * When disabled (default), the ConfigProvider only consumes the explicit
   * `theme` prop and never reads any storage, keeping the current behavior.
   * When enabled, the persisted theme config fills in keys not explicitly
   * provided by `theme`.
   *
   * @defaultValue false
   */
  persistTheme?: boolean;
  /**
   * The persisted theme config injected from the server.
   *
   * Used during SSR to render the same theme the client persisted; on the
   * client the localStorage is the source of truth.
   *
   * @type ThemeConfigState
   */
  themeConfig?: ThemeConfigState;
  /**
   * The server-side custom theme preset registry resolver.
   *
   * Maps a stored preset name to its definition so SSR can render custom
   * presets without localStorage access. Only used when `persistTheme` is
   * enabled on the server; on the client the presets table is the source of
   * truth.
   *
   * @param name The stored preset name to resolve.
   */
  presetProvider?: (name: string) => CustomThemeColorPreset | null | undefined;
  /**
   * Whether the component is running in a server environment.
   *
   * The UI library is pre-built, so `import.meta.env.SSR` is baked at build
   * time and cannot detect the consumer's runtime. This defaults to runtime
   * detection (`typeof window === 'undefined'`), and can be overridden with
   * the app's own flag (e.g. Nuxt's `import.meta.server`) when the app is
   * bundled for both server and client.
   *
   * @defaultValue isServerRuntime()
   */
  isServer?: boolean;
}

/**
 * Context for the ConfigProvider component.
 */
export interface ConfigProviderContext
  extends
    PropsToContext<
      Omit<ConfigProviderProps, 'iconRender' | 'presetProvider' | 'persistTheme' | 'themeConfig' | 'isServer'>
    >,
    Pick<ConfigProviderProps, 'iconRender'> {}

export type { ThemeOptions };

export { default as SConfigProvider } from './config-provider.vue';
export { useConfigProvider } from './context';
export { useTheme } from './use-theme';

export type * from '@soybeanjs/headless/config-provider';
export type { ConfigProviderProps, ConfigProviderThemeOptions, IconifyOptions, ThemeOptions } from './types';
export type { ThemeContext } from './use-theme';

import type { IconValue } from '@soybeanjs/headless';
import type { IconProps as IconifyIconProps } from '@iconify/vue';

/**
 * Properties for the Icon component.
 */
export interface IconProps extends Omit<IconifyIconProps, 'icon'> {
  /**
   * Icon rendered by the component.
   */
  icon: IconValue;
  /**
   * Whether the icon is hidden from assistive technology.
   *
   * Defaults to `true` for decorative icons. Set to `false` or provide `ariaLabel` / `ariaLabelledby` to expose the icon.
   */
  ariaHidden?: boolean;
  /**
   * Accessible label for the icon. When provided, `aria-hidden` is not set so the label is announced.
   */
  ariaLabel?: string;
  /**
   * ID of an element that labels the icon. When provided, `aria-hidden` is not set so the label is announced.
   */
  ariaLabelledby?: string;
}

export type { IconValue };

import { computed, defineComponent, h, onMounted, onUnmounted } from 'vue';
import { createTheme } from '@soybeanjs/theme';
import { THEME_PRESETS_STORAGE_KEY, THEME_STORAGE_KEY } from '@soybeanjs/theme/storage';
import type { ThemeConfigState } from '@soybeanjs/theme/storage';
import type { ConfigProviderProps } from './types';
import { createThemeContext, provideThemeContext } from './use-theme';

/**
 * Renders the theme `<style>` element. It is produced by a render function
 * because the SFC template compiler removes `<script>` / `<style>` tags from
 * component templates (they are treated as side-effect tags).
 */
const ThemeStyle = defineComponent({
  name: 'SoybeanUIThemeStyle',
  inheritAttrs: false,
  props: {
    css: { type: String, required: true },
    nonce: { type: String, default: undefined }
  },
  setup(styleProps) {
    return () =>
      h('style', {
        id: '__SoybeanUI_theme',
        innerHTML: styleProps.css,
        nonce: styleProps.nonce
      });
  }
});

/**
 * Owns all theme-related logic for the ConfigProvider: the reactive theme
 * context (created via `createThemeContext`), the derived theme CSS, and the
 * cross-tab storage refresh. Keeps the component SFC thin and the theme
 * concerns co-located with a single composable.
 */
export function useConfigProviderTheme(props: ConfigProviderProps) {
  // 响应式主题上下文：状态 / 持久化 / SSR / preset 全部收敛到 use-theme.ts，
  // 并通过 `provideThemeContext` 暴露给后代组件（`useTheme()`）。
  const themeContext = createThemeContext(props);
  provideThemeContext(themeContext);

  /**
   * theme CSS is rendered inline so it exists in the SSR HTML. The `useStyleTag`
   * approach is client-only and leaves SSR output without any theme variables.
   * The element is rendered on both server and client so hydration stays
   * consistent; reactivity keeps the content in sync when the theme changes.
   */
  const themeCss = computed(() => createTheme(themeContext.theme.value));

  // 跨标签页同步：storage 事件（其他标签页写入）使缓存失效并触发重读。
  // 主题配置走 `refreshThemeConfig`（重读 + 强制重派生）；自定义 preset 表走
  // `refreshPresetsSnapshot`。仅当 `persistTheme` 开启时才注册监听。
  const handleStorage = (event: StorageEvent): void => {
    if (event.key === THEME_STORAGE_KEY) {
      themeContext.refreshThemeConfig();
    } else if (event.key === THEME_PRESETS_STORAGE_KEY) {
      themeContext.refreshPresetsSnapshot?.();
    }
  };

  onMounted(() => {
    if (props.persistTheme) {
      window.addEventListener('storage', handleStorage);
    }
  });

  onUnmounted(() => {
    window.removeEventListener('storage', handleStorage);
  });

  /**
   * 写回持久化主题配置并同步内存状态，使下游主题派生无需重读存储。
   * 通过 `defineExpose` 暴露给应用层。
   */
  const commitThemeConfig = (config: ThemeConfigState): void => {
    themeContext.setThemeState(config);
  };

  return { themeCss, ThemeStyle, commitThemeConfig };
}

export * from './config';
export * from './use-theme-settings';
export * from './use-theme-variants';

export type * from './types';

import type { ToastProviderProps as _ToastProviderProps, ToastUi } from '@soybeanjs/headless/toast';
import type { ThemeSize } from '@/theme';

/**
 * Properties for the ToastProvider component.
 */
export interface ToastProviderProps extends _ToastProviderProps {
  /**
   * Visual size of the component.
   */
  size?: ThemeSize;
  /**
   * Per-slot class overrides for the component.
   */
  ui?: ToastUi;
}

import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import type { ComputedRef, Ref, ShallowRef } from 'vue';
import { useContext } from '@soybeanjs/headless/composables';
import type {
  ColorValue,
  DarkSelectorValue,
  ThemeMode,
  ThemeModePreference,
  ThemeOptions,
  ThemeOverrides,
  ThemePreset,
  ThemeRadiusValue,
  ThemeSizeValue,
  BaseColorKey,
  PrimaryColorKey
} from '@soybeanjs/theme';
import { isServerRuntime } from '@soybeanjs/theme/ssr';
import {
  getStoredThemeConfig,
  getStoredThemePresets,
  removeStoredThemePreset,
  setStoredThemeConfig,
  setStoredThemePreset
} from '@soybeanjs/theme/storage';
import type {
  CustomThemeColorPreset,
  StoredThemePreset,
  ThemeConfigState,
  ThemePresetInput
} from '@soybeanjs/theme/storage';
import type { ConfigProviderProps } from './types';

const DEFAULT_BASE: BaseColorKey = 'zinc';
const DEFAULT_PRIMARY: PrimaryColorKey = 'indigo';
const DEFAULT_RADIUS: ThemeRadiusValue = 'md';
const DEFAULT_SIZE: ThemeSizeValue = 'md';
const DEFAULT_MODE: ThemeModePreference = 'light';

/** the localStorage key carrying the currently applied custom preset name */
const APPLIED_PRESET_KEY = '__SOYBEAN_THEME_APPLIED_PRESET';

/**
 * The reactive theme context exposed by `SConfigProvider`.
 *
 * It owns the persistable theme state (`base` / `primary` / `radius` / `size` /
 * `mode`), the custom preset management, and the effective `theme` derived for
 * the provider. Consumers read it via `useTheme()` to drive their own theme UI
 * without prop drilling or app-level state stores.
 */
export interface ThemeContext {
  /** The base color preset key. */
  base: ShallowRef<BaseColorKey>;
  /** The primary color preset key. */
  primary: ShallowRef<PrimaryColorKey>;
  /** The border radius. */
  radius: ShallowRef<ThemeRadiusValue>;
  /** The component size / density. */
  size: ShallowRef<ThemeSizeValue>;
  /** The color scheme preference (`light` / `dark` / `auto`). */
  mode: ShallowRef<ThemeModePreference>;
  /** The effective (resolved) color scheme: `auto` follows the OS preference. */
  effectiveMode: ComputedRef<ThemeMode>;
  /** Set the border radius. */
  setRadius: (value: ThemeRadiusValue) => void;
  /** Set the component size / density. */
  setSize: (value: ThemeSizeValue) => void;
  /** Set the color scheme preference. */
  setMode: (value: ThemeModePreference) => void;
  /** The persisted custom theme presets table. */
  customPresets: Ref<Record<string, StoredThemePreset>>;
  /** The currently applied custom preset name, if any. */
  appliedPresetName: ShallowRef<string | null>;
  /** Save the current primary color as a custom preset. */
  savePreset: (name: string) => boolean;
  /** Remove a custom preset. */
  removePreset: (name: string) => boolean;
  /** Apply a custom preset by name. */
  applyPreset: (name: string) => void;
  /** Clear the applied custom preset. */
  resetPreset: () => void;
  /** Overwrite the full persistable theme state (base/primary/radius/size/mode/…). */
  setThemeState: (config: ThemeConfigState) => void;
  /** The effective theme merged from the internal state and the `theme` prop. */
  theme: ComputedRef<ThemeOptions>;
}

export const [provideThemeContext, useTheme] = useContext<ThemeContext>('UiThemeContext');

/** The internal theme context held by `SConfigProvider` (adds storage helpers). */
export type ConfigProviderThemeContext = ThemeContext & {
  /** Overwrite the internal theme state (used by cross-tab sync and `commitThemeConfig`). */
  setThemeState: (config: ThemeConfigState) => void;
  /** Re-read the persisted theme config from storage and force a re-derive (cross-tab sync). */
  refreshThemeConfig: () => void;
  /** Re-read the custom presets table from localStorage. */
  refreshPresetsSnapshot: () => void;
};

const getStoredPresetColors = (presetName: string): CustomThemeColorPreset | undefined => {
  const preset = getStoredThemePresets()?.presets[presetName];

  return preset ? { light: preset.light, ...(preset.dark ? { dark: preset.dark } : {}) } : undefined;
};

/**
 * resolve the dark mode class name from a `darkSelector` value.
 *
 * - 'class' → 'dark'
 * - 'media' → `null` (media queries follow the OS preference, no class toggled)
 * - any other string is a custom class selector used verbatim (dot stripped).
 */
const getDarkClass = (selector: DarkSelectorValue): string | null => {
  if (selector === 'media') {
    return null;
  }

  if (selector === 'class') {
    return 'dark';
  }

  return selector.replace(/^\./, '');
};

/**
 * whether a preset input is an inline color preset (mode-split, carries
 * `light`). A reference-only input carries just `name` and no `light`.
 */
const isInlineColorPreset = (preset: ThemePresetInput | undefined): preset is ThemePreset =>
  !!preset && 'light' in preset;

/**
 * Create the theme context for a `SConfigProvider` instance.
 *
 * The persistable theme state is initialized once from the persisted source
 * (the injected `themeConfig` on the server, localStorage on the client) and
 * kept in sync on every change, so the theme survives across refreshes and
 * matches between server and client rendering.
 */
export function createThemeContext(props: ConfigProviderProps): ConfigProviderThemeContext {
  const isServer = props.isServer ?? isServerRuntime();

  // —— 初始主题状态：persistTheme 关闭时不读任何存储；开启时优先注入的
  //    themeConfig（SSR），否则客户端从 localStorage 解析。服务端没有
  //    localStorage，首帧由内联脚本（createThemeInitScript）在客户端应用 ——
  let persisted: ThemeConfigState | null = null;

  if (props.persistTheme) {
    if (props.themeConfig) {
      // 显式注入的 themeConfig（SSR）优先，避免读取 localStorage
      persisted = props.themeConfig;
    } else if (!isServer) {
      persisted = getStoredThemeConfig();
    }
  }

  const themeState = reactive<ThemeConfigState>({
    ...persisted,
    base: persisted?.base ?? DEFAULT_BASE,
    primary: persisted?.primary ?? DEFAULT_PRIMARY,
    radius: persisted?.radius ?? DEFAULT_RADIUS,
    size: persisted?.size ?? DEFAULT_SIZE,
    mode: persisted?.mode ?? DEFAULT_MODE
  });

  const base = computed<BaseColorKey>({
    get: () => themeState.base ?? DEFAULT_BASE,
    set: value => {
      themeState.base = value;
    }
  });
  const primary = computed<PrimaryColorKey>({
    get: () => themeState.primary ?? DEFAULT_PRIMARY,
    set: value => {
      themeState.primary = value;
    }
  });
  const radius = computed<ThemeRadiusValue>({
    get: () => themeState.radius ?? DEFAULT_RADIUS,
    set: value => {
      themeState.radius = value as ThemeRadiusValue;
    }
  });
  const size = computed<ThemeSizeValue>({
    get: () => themeState.size ?? DEFAULT_SIZE,
    set: value => {
      themeState.size = value as ThemeSizeValue;
    }
  });
  const mode = computed<ThemeModePreference>({
    get: () => themeState.mode ?? DEFAULT_MODE,
    set: value => {
      themeState.mode = value;
    }
  });

  // —— auto 模式的系统偏好解析：跟踪 `prefers-color-scheme`，SSR 下无
  //    matchMedia 时回退为 light，首帧由 createThemeInitScript 在浏览器处理 ——
  const systemDark = ref(false);
  let mql: MediaQueryList | undefined;

  if (!isServer && typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
    mql = window.matchMedia('(prefers-color-scheme: dark)');
    systemDark.value = mql.matches;
  }

  const onSystemColorChange = (event: MediaQueryListEvent): void => {
    systemDark.value = event.matches;
  };

  mql?.addEventListener('change', onSystemColorChange);

  onUnmounted(() => {
    mql?.removeEventListener('change', onSystemColorChange);
  });

  /** `auto` 解析为系统偏好；显式 `light` / `dark` 原样返回 */
  const effectiveMode = computed<ThemeMode>(() =>
    mode.value === 'auto' ? (systemDark.value ? 'dark' : 'light') : mode.value
  );

  // —— 持久化：state 变化时写 localStorage，保证刷新后主题一致 ——
  watch(
    themeState,
    value => {
      if (!props.persistTheme) {
        return;
      }

      setStoredThemeConfig(value);
    },
    { deep: true }
  );

  // —— 暗色模式 class 同步（首帧前由 createThemeInitScript 应用，此处幂等并负责运行中切换）——
  // class 名与新的 darkSelector 机制保持一致：'media' 不切换任何 class。
  //
  // 切换时临时禁用 CSS 过渡（复刻 @vueuse/core useColorMode 的 disableTransition
  // 手法）：注入 `*{transition:none!important}` → 切换 class → 强制 reflow → 移除。
  // 否则带 `transition-all` 的组件（如按钮）会相对无过渡的页面背景延迟 150ms 才变色。
  //
  // 监听 `effectiveMode`（而非偏好 `mode`）：`auto` 会解析为系统 `prefers-color-scheme`，
  // 且系统偏好变化时 computed 重新求值，从而在 `auto` 下也能随 OS 明暗切换同步 class。
  watch(
    effectiveMode,
    value => {
      if (typeof document === 'undefined') {
        return;
      }

      const darkClass = getDarkClass(props.theme?.darkSelector ?? 'class');

      if (!darkClass) {
        return;
      }

      const disableTransitionsStyle = document.createElement('style');
      disableTransitionsStyle.appendChild(
        document.createTextNode(
          '*,*::before,*::after{-webkit-transition:none!important;-moz-transition:none!important;-o-transition:none!important;-ms-transition:none!important;transition:none!important}'
        )
      );
      document.head.appendChild(disableTransitionsStyle);

      document.documentElement.classList.toggle(darkClass, value === 'dark');

      // 强制浏览器同步重算样式，确保禁用过渡的规则在 class 切换前生效
      void window.getComputedStyle(disableTransitionsStyle).opacity;
      document.head.removeChild(disableTransitionsStyle);
    },
    { immediate: true }
  );

  // —— 缓存失效版本：storage 事件触发后递增，强制主题重派生（createTheme）——
  const cacheVersion = ref(0);

  // —— 自定义 preset ——
  const customPresets = ref<Record<string, StoredThemePreset>>({});
  const appliedPresetName = ref<string | null>(
    typeof document !== 'undefined' ? localStorage.getItem(APPLIED_PRESET_KEY) : null
  );

  const refreshPresets = (): void => {
    customPresets.value = getStoredThemePresets()?.presets ?? {};
  };

  /**
   * 跨标签页同步：另开标签页写入 stored theme 后，重读并同步到内存状态，
   * 递增缓存版本强制主题重派生。`themeConfig` 注入（SSR）时不重读 localStorage。
   */
  const refreshThemeConfig = (): void => {
    if (!props.persistTheme || props.themeConfig) {
      return;
    }

    const stored = getStoredThemeConfig();

    if (stored) {
      Object.assign(themeState, stored);
    }

    cacheVersion.value++;
  };

  onMounted(refreshPresets);

  const setAppliedPreset = (name: string | null): void => {
    appliedPresetName.value = name;

    if (typeof document === 'undefined') {
      return;
    }

    if (name) {
      localStorage.setItem(APPLIED_PRESET_KEY, name);
    } else {
      localStorage.removeItem(APPLIED_PRESET_KEY);
    }
  };

  const savePreset = (name: string): boolean => {
    const preset: StoredThemePreset = {
      name,
      version: '1.0.0',
      light: {
        primary: `${primary.value}.600` as ColorValue,
        ring: `${primary.value}.500` as ColorValue
      },
      dark: {
        primary: `${primary.value}.400` as ColorValue,
        ring: `${primary.value}.300` as ColorValue
      }
    };

    const saved = setStoredThemePreset(preset);

    if (saved) {
      refreshPresets();
    }

    return saved;
  };

  const removePreset = (name: string): boolean => {
    const removed = removeStoredThemePreset(name);

    if (removed) {
      refreshPresets();
      if (appliedPresetName.value === name) {
        setAppliedPreset(null);
      }
    }

    return removed;
  };

  const applyPreset = (name: string): void => {
    setAppliedPreset(name);
  };

  const resetPreset = (): void => {
    setAppliedPreset(null);
  };

  // —— 有效主题：显式 theme prop 覆盖内部状态 ——
  const resolvePreset = (): CustomThemeColorPreset | undefined => {
    const input = props.theme?.preset;

    // 内联 mode-split preset（自定义颜色）直接使用，不受 persistTheme 限制
    if (isInlineColorPreset(input)) {
      return input;
    }

    // 具名 preset 引用（{ name }，复用引擎 ThemePreset.name）或当前应用的 preset
    const presetName = input?.name ?? appliedPresetName.value;

    if (!presetName) {
      return undefined;
    }

    if (!props.persistTheme) {
      return undefined;
    }

    // SSR：走注入的 presetProvider（应用层注册表）；客户端：读本地 presets 表。
    const preset = isServer ? (props.presetProvider?.(presetName) ?? undefined) : getStoredPresetColors(presetName);

    if (!preset && isServer) {
      console.warn(`[SConfigProvider] theme preset "${presetName}" not found, falling back to built-in colors.`);
    }

    return preset;
  };

  const theme = computed<ThemeOptions>(() => {
    // 依赖缓存版本：storage 事件置脏后强制重派生（createTheme 重新执行）
    void cacheVersion.value;

    const t = props.theme ?? {};

    // 内联颜色预设（原 preset 内联部分）→ overrides；具名 preset 引用在
    // resolvePreset 中已解析为颜色。显式 `overrides` 优先于解析出的 preset。
    const colorPreset = resolvePreset();

    const overrides: ThemeOverrides | undefined =
      t.overrides ??
      themeState.overrides ??
      (colorPreset
        ? {
            light: colorPreset.light,
            ...(colorPreset.dark ? { dark: colorPreset.dark } : {})
          }
        : undefined);

    return {
      base: t.base ?? themeState.base ?? DEFAULT_BASE,
      primary: t.primary ?? themeState.primary ?? DEFAULT_PRIMARY,
      feedback: t.feedback ?? themeState.feedback,
      chart: t.chart ?? themeState.chart,
      sidebar: t.sidebar ?? themeState.sidebar,
      sidebarDerive: t.sidebarDerive ?? themeState.sidebarDerive,
      overrides,
      // size/radius 作为顶层 base tokens 传入，与新的 createTheme 签名保持一致：
      // 来源为持久化状态 → size prop。
      size: t.size ?? themeState.size ?? props.size ?? DEFAULT_SIZE,
      radius: t.radius ?? themeState.radius ?? DEFAULT_RADIUS,
      format: t.format ?? themeState.format,
      lightLevel: t.lightLevel ?? themeState.lightLevel,
      darkLevel: t.darkLevel ?? themeState.darkLevel,
      borderOpacity: t.borderOpacity ?? themeState.borderOpacity,
      styleTarget: t.styleTarget,
      darkSelector: t.darkSelector
    };
  });

  return {
    base,
    primary,
    radius,
    size,
    mode,
    effectiveMode,
    setRadius: value => {
      radius.value = value;
    },
    setSize: value => {
      size.value = value;
    },
    setMode: value => {
      mode.value = value;
    },
    customPresets,
    appliedPresetName,
    savePreset,
    removePreset,
    applyPreset,
    resetPreset,
    theme,
    setThemeState: (config: ThemeConfigState) => {
      Object.assign(themeState, config);
    },
    refreshThemeConfig,
    refreshPresetsSnapshot: refreshPresets
  };
}

